"""Translations for the built-in template catalog (v2.21.1).

One flat table keyed by the ENGLISH source string (template names, task
names and task notes share it — the recurring task names like "Annual
Service" or "Filter Cleaning" are deduplicated automatically). Consumers
call :func:`localize_template_text` with the 2-letter language from
``helpers.i18n.normalize_language``; unknown strings or languages fall back
to the English original, so a new template works everywhere immediately and
gains translations incrementally.
"""

